// İsim Şehir sütunları ve harfleri.

class PCard {
  final String emoji;

  /// Kartın adı 33 dilde (studio-core Strings.languages sırası).
  final List<String> names;

  /// a hayvan, f yiyecek, o eşya, j meslek, s spor, v taşıt, n doğa, x eylem.
  final String cat;

  /// 0 çocuk, 1 aile, 2 herkes (kart paketi seçimi).
  final int tier;
  const PCard(this.emoji, this.names, this.cat, this.tier);

  String get tr => names[0];
  String get en => names[1];
}

class PPlace {
  final String emoji;
  final List<String> names;
  const PPlace(this.emoji, this.names);
}

class PTabu {
  final String emoji;
  final String word;
  final List<String> no;
  final int tier;
  const PTabu(this.emoji, this.word, this.no, this.tier);
}

class PPrompt {
  final int tier;
  final String text;
  const PPrompt(this.tier, this.text);
}

